// Helper: convert S3 URL to proxied path so auth headers work and canvas doesn't get tainted
const S3_HOST = 'stasht-data.s3.us-east-2.amazonaws.com';
const LIVE_ORIGIN = 'https://studio.stasht.com';
function toProxiedUrl(imageSrc: string): string {
  try {
    const url = new URL(imageSrc);
    if (url.hostname === S3_HOST) return `/s3-proxy${url.pathname}${url.search}`;
    if (url.origin === LIVE_ORIGIN && url.pathname.startsWith('/s3-proxy')) return `${url.pathname}${url.search}`;
  } catch { /* not a valid URL */ }
  return imageSrc;
}

// Convert any proxied URL back to a direct S3 URL (fallback when proxy fails)
function toDirectS3Url(imageSrc: string): string {
  try {
    if (imageSrc.startsWith('/s3-proxy/')) {
      return `https://${S3_HOST}${imageSrc.slice('/s3-proxy'.length)}`;
    }
    const url = new URL(imageSrc);
    if (url.origin === LIVE_ORIGIN && url.pathname.startsWith('/s3-proxy/')) {
      return `https://${S3_HOST}${url.pathname.slice('/s3-proxy'.length)}${url.search}`;
    }
  } catch { /* not a valid URL */ }
  return imageSrc;
}

// Helper: get cropped image as base64 data URL
const getCroppedImg = async (imageSrc: string, pixelCrop: { x: number; y: number; width: number; height: number }): Promise<string> => {
  let objectUrl: string | null = null;

  const isLocal = imageSrc.startsWith('blob:') || imageSrc.startsWith('data:');
  const fetchSrc = isLocal ? imageSrc : toProxiedUrl(imageSrc);

  if (!isLocal) {
    // Try without auth first — Netlify proxies directly to S3 which doesn't accept Bearer tokens
    try {
      const resp = await fetch(fetchSrc);
      if (resp.ok) objectUrl = URL.createObjectURL(await resp.blob());
    } catch { /* fall through */ }

    // Retry with auth token in case a backend proxy requires it
    if (!objectUrl) {
      const token = localStorage.getItem('stasht_token');
      const headers: HeadersInit = token ? { Authorization: `Bearer ${token}` } : {};
      try {
        const resp = await fetch(fetchSrc, { headers, credentials: 'include' });
        if (resp.ok) objectUrl = URL.createObjectURL(await resp.blob());
      } catch { /* fall through to direct load */ }
    }
  }

  const image = new Image();
  if (objectUrl) {
    // Blob URL — no CORS needed
    image.src = objectUrl;
  } else {
    // Proxy failed — fall back to direct S3 URL with crossOrigin so canvas won't be tainted
    const directSrc = isLocal ? imageSrc : toDirectS3Url(imageSrc);
    image.crossOrigin = 'anonymous';
    image.src = directSrc;
  }
  await new Promise((resolve, reject) => { image.onload = resolve; image.onerror = reject; });

  const canvas = document.createElement('canvas');
  canvas.width = pixelCrop.width;
  canvas.height = pixelCrop.height;
  const ctx = canvas.getContext('2d')!;
  ctx.drawImage(image, pixelCrop.x, pixelCrop.y, pixelCrop.width, pixelCrop.height, 0, 0, pixelCrop.width, pixelCrop.height);
  const result = canvas.toDataURL('image/jpeg', 0.9);
  if (objectUrl) URL.revokeObjectURL(objectUrl);
  return result;
};

// Face crop component - shows only the face area using bounding box from AI scan
const FaceCrop = ({
  src,
  bbox,
  size,
  rounded = false,
}: {
  src: string;
  bbox: { left: number; top: number; width: number; height: number } | null | undefined;
  size: number;
  rounded?: boolean;
}) => {
  const borderRadius = rounded ? '50%' : '8px';

  if (!bbox || !bbox.width || !bbox.height) {
    return (
      <div style={{ width: size, height: size, borderRadius, overflow: 'hidden', flexShrink: 0 }}>
        <img src={src} alt="" style={{ width: '100%', height: '100%', objectFit: 'cover' }} />
      </div>
    );
  }

  const { left, top, width, height } = bbox;
  const PADDING = 0.25; // 25% padding around face for context

  const cx = left + width / 2;
  const cy = top + height / 2;

  // Scale so padded face region fills the container
  const S = 1 / (Math.max(width, height) * (1 + 2 * PADDING));

  // Translate so face center aligns with container center
  const translateX = size * (0.5 - cx * S);
  const translateY = size * (0.5 - cy * S);

  return (
    <div style={{ width: size, height: size, borderRadius, overflow: 'hidden', position: 'relative', flexShrink: 0 }}>
      <img
        src={src}
        alt=""
        style={{
          position: 'absolute',
          width: size,
          height: size,
          objectFit: 'cover',
          transformOrigin: '0 0',
          transform: `translate(${translateX}px, ${translateY}px) scale(${S})`,
        }}
      />
    </div>
  );
};

