  // Fetch memory details and activity on component mount and memoryId change
  // Collaborators are now extracted from the memory detail response
  useEffect(() => {
    fetchMemoryDetails();
    // These hit memory-only endpoints; skip for a Shopify collection detail.
    if (!isShopifyCollection) {
      fetchMemoryActivity();
      fetchPublishHistory();
    }
  }, [memoryId]);

  // Refresh Analytics tab data every time the tab is opened so it reflects the
  // latest server state — publish history (incl. CTA click counts) and recent activity.
  useEffect(() => {
    if (activeTab === 'analytics') {
      fetchPublishHistory();
      fetchMemoryActivity();
    }
  }, [activeTab]);

  // After caption save + data refresh, scroll back to the saved post
  useEffect(() => {
    const targetId = scrollToPostIdAfterRefresh.current;
    if (!targetId || !apiMemoryData) return;

    // Delay so DOM has time to render the refreshed posts
    const timer = setTimeout(() => {
      const el = document.querySelector(`[data-post-id="${targetId}"]`) as HTMLElement | null;
      if (el) {
        el.scrollIntoView({ behavior: 'smooth', block: 'center' });
      }
      scrollToPostIdAfterRefresh.current = null;
    }, 400);

    return () => clearTimeout(timer);
  }, [apiMemoryData]);

  // Generate share link when modal opens or role changes
  useEffect(() => {
    if (isGenerateQROpen && memoryId) {
      generateShareLink(selectedRole);
    }
  }, [isGenerateQROpen, selectedRole, memoryId]);

  // Pull-to-refresh handlers
  const handleTouchStart = (e: React.TouchEvent) => {
    if (isRefreshing) return;

    const scrollTop = (e.currentTarget as HTMLElement).scrollTop;
    if (scrollTop === 0) {
      setTouchStartY(e.touches[0].clientY);
    }
  };

  const handleTouchMove = (e: React.TouchEvent) => {
    if (isRefreshing || touchStartY === 0) return;

    const scrollTop = (e.currentTarget as HTMLElement).scrollTop;
    if (scrollTop > 0) {
      setIsPulling(false);
      setPullDistance(0);
      setTouchStartY(0);
      return;
    }

    const currentY = e.touches[0].clientY;
    const distance = currentY - touchStartY;

    if (distance > 0) {
      setIsPulling(true);
      setPullDistance(Math.min(distance, pullThreshold * 1.5));
    }
  };

  const handleTouchEnd = async () => {
    if (isRefreshing) return;

    setTouchStartY(0);

    if (pullDistance >= pullThreshold) {
      console.log('🔄 PULL-TO-REFRESH: Starting refresh...');
      setIsRefreshing(true);
      setIsPulling(false);

      try {
        await Promise.all([
          fetchMemoryDetails(true), // Skip loading state for pull-to-refresh
          fetchMemoryActivity(true) // Skip loading state for pull-to-refresh
        ]);
        console.log('✅ PULL-TO-REFRESH: Data refreshed successfully');
        // toast.success("Moment added! It will appear on the timeline after admin review.");
      } catch (error) {
        console.error('❌ PULL-TO-REFRESH: Error refreshing memory:', error);
      } finally {
        setTimeout(() => {
          setIsRefreshing(false);
          setPullDistance(0);
          console.log('🏁 PULL-TO-REFRESH: Complete');
        }, 500);
      }
    } else {
      setIsPulling(false);
      setPullDistance(0);
    }
  };

  // Handle camera button click - show glass options sheet
  const handleCameraClick = () => {
    setShowCameraOptions(true);
    setShowMoreCameraOptions(false);
  };

  // Handle take photo option
  const handleTakePhoto = () => {
    setShowCameraOptions(false);
    setShowCameraInterface(true);
  };

  // Handle choose from library option
  const handleChooseFromLibrary = () => {
    setShowCameraOptions(false);
    if (isMobile) {
      triggerMobileFilePicker((e) => handleMediaLibrarySelection(e as any), false);
    } else if (mediaLibraryInputRef.current) {
      mediaLibraryInputRef.current.click();
    }
  };

  // Handle camera interface capture
  const handleCameraInterfaceCapture = (files: File[]) => {
    if (files && files.length > 0) {
      // Convert files array to FileList-like object
      const dataTransfer = new DataTransfer();
      files.forEach(file => dataTransfer.items.add(file));
      const fileList = dataTransfer.files;

      // Store captured files and open Add Moment modal
      setCapturedFiles(fileList);
      setShowCameraInterface(false);
      setIsAddMomentModalOpen(true);
      console.log('📷 Camera captured:', files[0].name);
    }
  };

  // Handle camera capture
  const handleCameraCapture = (event: React.ChangeEvent<HTMLInputElement>) => {
    const files = event.target.files;
    if (files && files.length > 0) {
      // Store captured files and open Add Moment modal
      setCapturedFiles(files);
      setIsAddMomentModalOpen(true);
      console.log('📷 Camera captured:', files[0].name);
    }

    // Reset input value to allow capturing the same file again
    if (event.target) {
      event.target.value = '';
    }
  };

  // Intersection Observer: mark new images as seen when they scroll into viewport
  useEffect(() => {
    if (!apiMemoryData) return;

    let observer: IntersectionObserver;

    const setup = () => {
      const newEls = Array.from(
        document.querySelectorAll<HTMLElement>('[data-is-new="true"]')
      );
      if (newEls.length === 0) return;

      observer = new IntersectionObserver(
        (entries) => {
          entries.forEach(async (entry) => {
            if (!entry.isIntersecting) return;
            const imageId = (entry.target as HTMLElement).dataset.imageId;
            if (!imageId || seenNewImagesRef.current.has(imageId)) return;

            seenNewImagesRef.current.add(imageId);
            observer.unobserve(entry.target);

            try {
              await apiRequest(`/memories/${imageId}/mark-seen`, { method: 'POST' });
              console.log(`✅ Marked image ${imageId} as seen`);
              setApiMemoryData((prev: any) => {
                if (!prev) return prev;
                return {
                  ...prev,
                  posts: prev.posts?.map((post: any) =>
                    post.id?.toString() === imageId ? { ...post, is_new: 0 } : post
                  ),
                  new_images: Math.max(0, (prev.new_images || 0) - 1),
                };
              });
            } catch (err) {
              console.error(`❌ Failed to mark image ${imageId} as seen`, err);
              seenNewImagesRef.current.delete(imageId);
            }
          });
        },
        { threshold: 0.5 }
      );

      newEls.forEach(el => observer.observe(el));
    };

    // rAF ensures DOM is fully painted before querying
    const raf = requestAnimationFrame(setup);

    return () => {
      cancelAnimationFrame(raf);
      observer?.disconnect();
    };
  }, [apiMemoryData]);


  const handleAiScanClick = async (e: React.MouseEvent) => {
    console.log('🔘 AI Scan button clicked');
    e.stopPropagation();
    e.preventDefault();

    // Don't allow clicking while scanning
    if (isAiScanning) {
      console.log('⏸️ Already scanning, ignoring click');
      return;
    }

    try {
      console.log('💳 Checking credits...');
      // Check if user has sufficient credits
      const creditCheck = await aiCreditsAPI.checkSufficientCredits('ai_memory_wizard', 2);
      console.log('💳 Credit check result:', creditCheck);

      if (creditCheck && creditCheck.has_sufficient_credits) {
        // Show confirmation popover
        console.log('✅ Credits sufficient, showing confirmation popover');
        setShowCreditConfirmModal(true);
      } else {
        const available = creditCheck?.total_available ?? 0;
        console.log('❌ Insufficient credits:', available);
        setAiScanAvailableCredits(available);
        setShowAiScanCreditsModal(true);
      }
    } catch (error) {
      console.error('❌ Error checking credits:', error);
      toast.error('Failed to check credits');
    }
  };

  // Handle AI Scan confirmation
  const handleAiScanConfirm = async () => {
    console.log('🎯 handleAiScanConfirm called');
    setShowCreditConfirmModal(false);
    setIsAiScanning(true);
    setAiScanProgress(0);

    // Start slow progress simulation: 0→70% over ~30s, then 70→90% over ~40s, holds at 90 until done
    let progress = 0;
    const clearScanInterval = () => {
      if (aiScanIntervalRef.current) {
        clearInterval(aiScanIntervalRef.current);
        aiScanIntervalRef.current = null;
      }
    };

    // Phase 1: 0 → 70% each tick = ~700ms → ~50s total
    aiScanIntervalRef.current = setInterval(() => {
      progress += 1;
      setAiScanProgress(progress);
      if (progress >= 70) {
        clearScanInterval();
        // Phase 2: 70 → 90% each tick = ~1400ms → ~28s total
        aiScanIntervalRef.current = setInterval(() => {
          progress += 1;
          setAiScanProgress(progress);
          if (progress >= 90) {
            clearScanInterval();
            // Hold at 90 — will jump to 100 when API responds
          }
        }, 1400);
      }
    }, 700);

    try {
      // Collect all image URLs from the memory
      const photoUrls: string[] = [];

      // Get images from memoryImagesWithSubImages
      if (memoryImagesWithSubImages && memoryImagesWithSubImages.length > 0) {
        memoryImagesWithSubImages.forEach((img: any) => {
          if (img.src) {
            photoUrls.push(img.src);
          }
          // Also collect sub-images if they exist
          if (img.subImages && img.subImages.length > 0) {
            img.subImages.forEach((subImg: any) => {
              if (subImg.src) {
                photoUrls.push(subImg.src);
              }
            });
          }
        });
      }

      // Remove duplicates
      const uniquePhotoUrls = [...new Set(photoUrls)];

      if (uniquePhotoUrls.length === 0) {
        toast.error('No images found in this campaign to scan');
        setIsAiScanning(false);
        return;
      }

      console.log('🔍 AI Scan - Analyzing', uniquePhotoUrls.length, 'images for memory:', actualMemoryId);
      console.log('📦 Request payload:', { cluster_type: 'faces', memory_id: actualMemoryId, photos_count: uniquePhotoUrls.length });

      // Call the AI analyze API using apiRequest
      console.log('🚀 Sending request to API: /reactapi/ai/analyze/upload');

      const response = await apiRequest('/ai/analyze/upload', {
        method: 'POST',
        body: JSON.stringify({
          cluster_type: 'faces',
          memory_id: actualMemoryId,
          photos: uniquePhotoUrls,
        }),
      });

      console.log('📬 Response received:', response);

      // apiRequest handles errors and returns parsed data
      const data = response.data?.data || response.data || response;
      console.log('✅ AI Scan Results:', data);

      // Set results and activate AI scan view
      setAiScanResults(data);
      setIsAiScanActive(true);

      const totalPeople = data.clusters?.faces?.length || 0;
      toast.success(`Found ${totalPeople} ${totalPeople === 1 ? 'person' : 'people'} in your photos`);
    } catch (error) {
      console.error('Error during AI scan:', error);
      toast.error('AI scan failed. Please try again.');
    } finally {
      clearScanInterval();
      setAiScanProgress(100);
      setTimeout(() => {
        setIsAiScanning(false);
        setAiScanProgress(0);
      }, 600);
    }
  };

  // Handle person click to show detail view
  const handlePersonClick = (cluster: any) => {
    setSelectedPerson(cluster);
    setSelectedFacePhotoIds(new Set());
  };

  // Handle back to list from detail view
  const handleBackToList = () => {
    setSelectedPerson(null);
    setSelectedFacePhotoIds(new Set());
  };

  // Handle saving a face cluster name via API
  const handleSaveClusterName = async (clusterId: string, name: string) => {
    const trimmed = name.trim();
    setEditingClusterId(null);
    setEditingClusterName("");

    if (!trimmed) return; // nothing to save if empty

    // Check for duplicate name in other clusters
    const isDuplicate = Object.entries(clusterNames).some(
      ([id, existingName]) => id !== clusterId && existingName.toLowerCase() === trimmed.toLowerCase()
    );
    if (isDuplicate) {
      toast.error(`"${trimmed}" already exists. Please use a different name.`);
      return;
    }

    const prevName = clusterNames[clusterId];
    // Optimistic update
    setClusterNames(prev => ({ ...prev, [clusterId]: trimmed }));

    try {
      const response = await apiRequest('/ai/face-cluster/name', {
        method: 'PUT',
        body: JSON.stringify({
          memory_id: Number(actualMemoryId),
          face_id: clusterId,
          name: trimmed,
        }),
      });
      if (response.success) {
        toast.success(`Person named "${trimmed}" saved`);
      } else {
        // Roll back on failure
        setClusterNames(prev => {
          const updated = { ...prev };
          if (prevName) updated[clusterId] = prevName;
          else delete updated[clusterId];
          return updated;
        });
        toast.error('Failed to save name. Please try again.');
      }
    } catch (error) {
      // Roll back on error
      setClusterNames(prev => {
        const updated = { ...prev };
        if (prevName) updated[clusterId] = prevName;
        else delete updated[clusterId];
        return updated;
      });
      toast.error('Failed to save name. Please try again.');
    }
  };

  // Handle saving all person details (name, tags, thumbnail) via POST /ai/face-cluster/update
  const handleSavePersonDetails = async (clusterId: string, name: string) => {
    const trimmedName = name.trim();

    // Optimistic UI updates
    if (trimmedName) {
      setClusterNames(prev => ({ ...prev, [clusterId]: trimmedName }));
    }
    if (editThumbnailPreview) {
      setClusterThumbnails(prev => ({ ...prev, [clusterId]: editThumbnailPreview }));
    }
    setIsEditingPersonCard(false);
    setEditTagInput('');
    setEditThumbnailPreview('');

    const formData = new FormData();
    formData.append('memory_id', String(Number(actualMemoryId)));
    formData.append('cluster_id', clusterId);
    if (trimmedName) formData.append('name', trimmedName);
    const tags = clusterTags[clusterId] || [];
    tags.forEach(tag => formData.append('tags[]', tag));

    // Convert base64 thumbnail to a real File and append
    if (editThumbnailPreview) {
      const byteString = atob(editThumbnailPreview.split(',')[1]);
      const ab = new ArrayBuffer(byteString.length);
      const ia = new Uint8Array(ab);
      for (let i = 0; i < byteString.length; i++) ia[i] = byteString.charCodeAt(i);
      const blob = new Blob([ab], { type: 'image/jpeg' });
      formData.append('thumbnail', blob, 'thumbnail.jpg');
    }

    try {
      const token = localStorage.getItem('stasht_token');
      const res = await fetch(`${getApiBaseUrl()}/ai/face-cluster/update`, {
        method: 'POST',
        headers: {
          ...(token ? { Authorization: `Bearer ${token}` } : {}),
        },
        body: formData,
      });
      const data = await res.json();
      if (data.success) {
        toast.success('Person details saved');
      } else {
        toast.error('Failed to save person details. Please try again.');
      }
    } catch (error) {
      toast.error('Failed to save person details. Please try again.');
    }
  };

  // Handle deleting selected face photos
  const handleDeleteFacePhotos = async () => {
    if (selectedFacePhotoIds.size === 0) return;
    setIsDeletingFacePhotos(true);
    try {
      const token = localStorage.getItem('stasht_token');
      // Concurrency-capped — a selection can span hundreds of face photos.
      await mapLimit(Array.from(selectedFacePhotoIds), (photoId) =>
        fetch(`${getApiBaseUrl()}/ai/face-photo/${photoId}`, {
          method: 'DELETE',
          headers: { ...(token ? { Authorization: `Bearer ${token}` } : {}) },
        })
      );

      // Remove deleted photos from aiScanResults in state
      setAiScanResults((prev: any) => {
        if (!prev?.clusters?.faces) return prev;
        return {
          ...prev,
          clusters: {
            ...prev.clusters,
            faces: prev.clusters.faces.map((cluster: any) => {
              const filteredImages = cluster.images.filter((img: any) => !selectedFacePhotoIds.has(String(img.id)));
              return { ...cluster, images: filteredImages, total_images: filteredImages.length };
            })
          }
        };
      });

      // Update selectedPerson to reflect removed images
      if (selectedPerson) {
        setSelectedPerson((prev: any) => {
          const filteredImages = prev.images.filter((img: any) => !selectedFacePhotoIds.has(String(img.id)));
          return { ...prev, images: filteredImages, total_images: filteredImages.length };
        });
      }

      setSelectedFacePhotoIds(new Set());
      toast.success(`${selectedFacePhotoIds.size} photo${selectedFacePhotoIds.size > 1 ? 's' : ''} deleted`);
    } catch (err) {
      console.error('Failed to delete face photos:', err);
      toast.error('Failed to delete photos. Please try again.');
    } finally {
      setIsDeletingFacePhotos(false);
    }
  };

  // Handle media library selection
  const handleMediaLibrarySelection = (event: React.ChangeEvent<HTMLInputElement>) => {
    const files = event.target.files;
    if (files && files.length > 0) {
      // Store selected files and open Add Moment modal
      setCapturedFiles(files);
      setIsAddMomentModalOpen(true);
      console.log('📁 Media library selected:', files[0].name);
    }

    // Reset input value to allow selecting the same file again
    if (event.target) {
      event.target.value = '';
    }
  };

  // Fallback to mock data if API data is not available
  const fallbackMemory = getMemoryDetails(memoryId);
  const memory = apiMemoryData || fallbackMemory;

  // IntersectionObserver for header image - detect when it scrolls out of view
  useEffect(() => {
    let headerObserver: IntersectionObserver;
    const rafId = requestAnimationFrame(() => {
      headerObserver = new IntersectionObserver(
        (entries) => {
          entries.forEach((entry) => {
            const hasScrolledPastTop = entry.boundingClientRect.top < 0;
            setIsHeaderImageScrolled(!entry.isIntersecting && hasScrolledPastTop);
          });
        },
        { root: null, rootMargin: '0px', threshold: 0 }
      );
      if (headerImageRef.current) {
        headerObserver.observe(headerImageRef.current);
      }
    });
    return () => {
      cancelAnimationFrame(rafId);
      headerObserver?.disconnect();
    };
  }, [apiMemoryData, activeTab]);

  // IntersectionObserver for scroll sync - track which memory card or HTML widget is visible
  useEffect(() => {
    let observer: IntersectionObserver;
    const rafId = requestAnimationFrame(() => {
      observer = new IntersectionObserver(
        (entries) => {
          entries.forEach((entry) => {
            if (entry.isIntersecting) {
              const widgetId = entry.target.getAttribute('data-widget-id');
              const ytWidgetId = entry.target.getAttribute('data-yt-widget-id');
              const quoteWId = entry.target.getAttribute('data-quote-widget-id');
              const ctaWId = entry.target.getAttribute('data-cta-widget-id');
              const lmId = entry.target.getAttribute('data-lm-id');
              const index = Number(entry.target.getAttribute('data-index'));
              if (lmId) {
                setActiveLmId(lmId);
                setActiveMemoryIndex(-1);
                setActiveHtmlWidgetId(null);
                setActiveYoutubeWidgetId(null);
                setActiveQuoteWidgetId(null);
                setActiveCtaWidgetId(null);
              } else if (quoteWId) {
                setActiveQuoteWidgetId(quoteWId);
                setActiveYoutubeWidgetId(null);
                setActiveHtmlWidgetId(null);
                setActiveCtaWidgetId(null);
                setActiveMemoryIndex(-1);
                setActiveLmId(null);
              } else if (ctaWId) {
                setActiveCtaWidgetId(ctaWId);
                setActiveQuoteWidgetId(null);
                setActiveYoutubeWidgetId(null);
                setActiveHtmlWidgetId(null);
                setActiveMemoryIndex(-1);
                setActiveLmId(null);
              } else if (ytWidgetId) {
                setActiveYoutubeWidgetId(ytWidgetId);
                setActiveQuoteWidgetId(null);
                setActiveHtmlWidgetId(null);
                setActiveCtaWidgetId(null);
                setActiveMemoryIndex(-1);
                setActiveLmId(null);
              } else if (widgetId) {
                setActiveHtmlWidgetId(widgetId);
                setActiveYoutubeWidgetId(null);
                setActiveQuoteWidgetId(null);
                setActiveCtaWidgetId(null);
                setActiveMemoryIndex(-1);
                setActiveLmId(null);
              } else if (!isNaN(index)) {
                setActiveMemoryIndex(index);
                setActiveHtmlWidgetId(null);
                setActiveYoutubeWidgetId(null);
                setActiveQuoteWidgetId(null);
                setActiveCtaWidgetId(null);
                setActiveLmId(null);
              }
            }
          });
        },
        {
          root: rightScrollContainerRef.current || null,
          rootMargin: '-20% 0px -60% 0px',
          threshold: 0
        }
      );
      memoryCardRefs.current.forEach((ref) => {
        if (ref) observer.observe(ref);
      });
      Object.values(htmlWidgetCardRefs.current).forEach((ref) => {
        if (ref) observer.observe(ref);
      });
      Object.values(youtubeWidgetCardRefs.current).forEach((ref) => {
        if (ref) observer.observe(ref);
      });
      Object.values(quoteWidgetCardRefs.current).forEach((ref) => {
        if (ref) observer.observe(ref);
      });
      Object.values(ctaWidgetCardRefs.current).forEach((ref) => {
        if (ref) observer.observe(ref);
      });
      Object.values(linkedMemoryCardRefs.current).forEach((ref) => {
        if (ref) observer.observe(ref);
      });
    });
    return () => {
      cancelAnimationFrame(rafId);
      observer?.disconnect();
    };
  }, [htmlWidgets, youtubeWidgets, quoteWidgets, ctaWidgets, apiMemoryData, activeTab, combinedTimeline]);

  // Shared view: scroll listener → shows sticky header once user scrolls past the cover image
  useEffect(() => {
    setSharedIsHeaderScrolled(false);
    const handleScroll = () => {
      const target = sharedMobileHeaderImgRef.current;
      if (!target) return;
      const rect = target.getBoundingClientRect();
      // Cover has scrolled out when its bottom is above the viewport top
      setSharedIsHeaderScrolled(rect.bottom < 0);
    };
    window.addEventListener('scroll', handleScroll, { passive: true });
    handleScroll(); // run once on mount to set initial state
    return () => window.removeEventListener('scroll', handleScroll);
  }, [apiMemoryData]);

  // Shared view: observer for desktop cards → drives activeMemoryIndex
  useEffect(() => {
    const cards = sharedDesktopCardRefs.current.filter(Boolean);
    if (cards.length === 0) return;
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            const index = Number(entry.target.getAttribute('data-index'));
            if (!isNaN(index)) setActiveMemoryIndex(index);
          }
        });
      },
      { root: sharedRightScrollRef.current || null, rootMargin: '-20% 0px -60% 0px', threshold: 0 }
    );
    cards.forEach((ref) => { if (ref) observer.observe(ref); });
    return () => observer.disconnect();
  }, [apiMemoryData, htmlWidgets, youtubeWidgets, quoteWidgets, ctaWidgets]);

  // Shared view: auto-scroll sidebar timeline item when activeMemoryIndex changes
  useEffect(() => {
    if (sharedIsHeaderScrolled) {
      const el = sharedTimelineRefs.current[activeMemoryIndex];
      if (el) el.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
    }
  }, [activeMemoryIndex, sharedIsHeaderScrolled]);

  // When scroll container reaches the bottom, activate the last combinedTimeline item
  useEffect(() => {
    const container = rightScrollContainerRef.current;
    if (!container) return;
    const handleScroll = () => {
      const atBottom = container.scrollHeight - container.scrollTop - container.clientHeight < 60;
      if (atBottom && combinedTimeline && combinedTimeline.length > 0) {
        const last = combinedTimeline[combinedTimeline.length - 1];
        if (last.type === 'linked') {
          setActiveLmId(last.id);
          setActiveMemoryIndex(-1);
        } else {
          const idx = sortedTimelinePostsRef.current.findIndex((p: any) => String(p.id) === last.id);
          if (idx !== -1) {
            setActiveMemoryIndex(idx);
            setActiveLmId(null);
          }
        }
      }
    };
    container.addEventListener('scroll', handleScroll, { passive: true });
    return () => container.removeEventListener('scroll', handleScroll);
  }, [combinedTimeline]);

  // Auto-scroll timeline item into view when activeMemoryIndex or activeLmId changes
  useEffect(() => {
    if (isHeaderImageScrolled) {
      const el = timelineItemRefs.current[activeMemoryIndex];
      if (el) {
        el.scrollIntoView({ behavior: 'smooth', block: 'center' });
      }
    } else {
      if (timelineScrollRef.current) {
        timelineScrollRef.current.scrollTo({ top: 0, behavior: 'smooth' });
      }
    }
  }, [activeMemoryIndex, isHeaderImageScrolled]);

  useEffect(() => {
    if (activeLmId && isHeaderImageScrolled) {
      const el = document.querySelector(`[data-lm-sidebar="${activeLmId}"]`) as HTMLElement | null;
      if (el) el.scrollIntoView({ behavior: 'smooth', block: 'center' });
    }
  }, [activeLmId, isHeaderImageScrolled]);

  // Reset custom order when sort changes (must be before early returns)
  useEffect(() => {
    setMediaCustomOrder([]);
  }, [mediaSortBy, mediaSortOrder]);

  // Compute set of image URLs that belong to hidden face clusters (must be before early returns)
  const hiddenImageUrls = useMemo(() => {
    const urls = new Set<string>();
    if (!aiScanResults?.clusters?.faces) return urls;
    aiScanResults.clusters.faces.forEach((cluster: any) => {
      if (hiddenClusterIds.has(cluster.cluster_id)) {
        (Array.isArray(cluster.images) ? cluster.images : []).forEach((img: any) => {
          if (img.url && !unhiddenImageUrls.has(img.url)) urls.add(img.url);
        });
        if (cluster.representative_image_url && !unhiddenImageUrls.has(cluster.representative_image_url))
          urls.add(cluster.representative_image_url);
      }
    });
    return urls;
  }, [hiddenClusterIds, unhiddenImageUrls, aiScanResults]);

  // Show loading state
  if (isLoadingMemory) {
    return (
      <div className="w-full space-y-8">
        <div className="flex items-center gap-4">
          <Button variant="ghost" size="sm" onClick={onBack}>
            <ArrowLeft className="w-4 h-4 mr-2" />
            Back
          </Button>
        </div>
        <div className="text-center py-12">
          <div className="w-8 h-8 border-2 border-[#6C60FF] border-t-transparent rounded-full animate-spin mx-auto mb-4"></div>
          <h2 className="text-xl font-semibold text-gray-900 mb-2">Loading campaign...</h2>
          <p className="text-gray-600">Fetching campaign details from server.</p>
        </div>
      </div>
    );
  }

  // Show error state
  if (apiError) {
    return (
      <div className="w-full space-y-8">
        <div className="flex items-center gap-4">
          <Button variant="ghost" size="sm" onClick={onBack}>
            <ArrowLeft className="w-4 h-4 mr-2" />
            Back
          </Button>
        </div>
        <div className="text-center py-12">
          <h2 className="text-xl font-semibold text-gray-900 mb-2">Error loading campaign</h2>
          <p className="text-gray-600 mb-4">{apiError}</p>
          <Button onClick={() => window.location.reload()} className="bg-[#6C60FF] hover:bg-[#5B4FE8] text-white">
            Try Again
          </Button>
        </div>
      </div>
    );
  }

  // Show not found state
  if (!memory) {
    return (
      <div className="w-full space-y-8">
        <div className="flex items-center gap-4">
          <Button variant="ghost" size="sm" onClick={onBack}>
            <ArrowLeft className="w-4 h-4 mr-2" />
            Back
          </Button>
        </div>
        <div className="text-center py-12">
          <h2 className="text-xl font-semibold text-gray-900 mb-2">Campaign not found</h2>
          <p className="text-gray-600">The campaign you're looking for doesn't exist or has been deleted.</p>
        </div>
      </div>
    );
  }

  // Map API data to UI-expected format with local updates applied
  const uiMemory = apiMemoryData ? {
    id: apiMemoryData.id,
    title: localMemoryUpdates?.title || apiMemoryData.title,
    category: localMemoryUpdates?.category || apiMemoryData.category?.name || 'Personal',
    thumbnail: (apiMemoryData.last_update_img || apiMemoryData.user?.profile_image || 'https://images.unsplash.com/photo-1507525428034-b723cf961d3e?w=400&h=300&fit=crop').replace(/\\\//g, '/'),
    dateRange: localMemoryUpdates?.dateRange || apiMemoryData.dates?.formatted_range || `${apiMemoryData.min_uploaded_img_date || 'Unknown'}`,
    location: {
      primary: localMemoryUpdates?.location || apiMemoryData.location || null
    },
    tags: (localMemoryUpdates?.label ? [localMemoryUpdates.label] : (apiMemoryData.sub_category?.name ? [apiMemoryData.sub_category.name] : [])),
    isPublic: apiMemoryData.published === 1 || false,
    createdDate: apiMemoryData.created_at,
    description: apiMemoryData.description
  } : {
    ...memory,
    tags: []
  };

  // Check if memory has "Suggested" category - make it read-only
  const isSuggestedCategory = uiMemory.category === 'Suggested';

  // Check if viewing as collaborator (for pull-to-refresh)
  const isCollaboratorView = currentUserRole === 'contributor' || currentUserRole === 'viewer' || currentUserRole === 'edit' || currentUserRole === 'view';

  // Check if current user is a collaborator (memory is shared with them), or force shared view
  const isSharedMemory = forceSharedView || apiMemoryData?.collaborator?.some((collab: any) => {
    // Check if current user's email or ID matches any collaborator
    if (!user) return false;

    const collabUser = collab.user;
    if (!collabUser) return false;

    // Match by email or user ID
    return (user.email && collabUser.email === user.email) ||
           (user.id && String(collabUser.id) === String(user.id));
  });

  const CategoryIcon = getCategoryIcon(uiMemory.category);
  const categoryColorHex = isSharedMemory
    ? '#EF4444' // Red color for shared memories
    : getCategoryColor(uiMemory.category, apiCategories.length > 0 ? apiCategories : categories);

  // Transform API posts to match UI expected format with enhanced filtering support
  const transformApiPosts = (apiPosts: any[]) => {
    if (!apiPosts || !Array.isArray(apiPosts)) return [];

    return apiPosts.map((post: any, index: number) => {
      // Debug log for rotation angle
      console.log(`🔄 Post ${post.id}: rotation_angle = ${post.rotation_angle}`);
      // Debug log for title field from API
      console.log(`📝 Post ${post.id}: title from API = "${post.title}", name from API = "${post.name}"`);

      return {
      id: post.id?.toString() || `post_${index}`,
      memoryId: uiMemory.id,
      name: post.name || null, // Preserve the name field from API
      title: post.title || '', // Only use actual title, don't fallback to name
      author: {
        name: post.user?.name || 'Unknown User',
        avatar: post.user?.profile_image ? post.user.profile_image.replace(/\\\//g, '/') : (post.user?.avatar ? post.user.avatar.replace(/\\\//g, '/') : null),
        id: post.user?.id?.toString() || post.user_id?.toString() || null,
        email: post.user?.email || null
      },
      content: post.description || '',
      image: post.image_link ? post.image_link.replace(/\\\//g, '/') : null,
      date: post.capture_date || new Date().toISOString(),
      likes: post.likes_count || 0,
      likes_count: post.likes_count || 0,
      comments: post.comments_count || 0,
      isLiked: post.is_liked || false,
      is_liked: post.is_liked || false,
      shares_count: post.shares_count || 0,
      location: post.location || null,
      tags: Array.isArray(post.tags) ? post.tags.map((t: any) => typeof t === 'string' ? t : t?.name).filter(Boolean) : [],
      // Shopify product fields (present only for Shopify collection products); drives the dedicated product card
      variants: Array.isArray(post.variants) ? post.variants : undefined,
      price: post.price ?? null,
      currency: post.currency ?? null,
      handle: post.handle ?? null,
      vendor: post.vendor ?? null,
      compare_at_price: post.compare_at_price ?? null,
      shop_domain: post.shop_domain ?? null,
      product_url: post.product_url ?? null,
      // Enhanced filtering properties based on actual API structure
      type: post.type || 'image', // image, video, text, etc.
      visibility: post.visibility || 'public',
      category: post.category || null,
      subcategory: post.subcategory || null,
      reactions: post.reactions || [],
      timestamp: post.created_at || post.capture_date || new Date().toISOString(),
      // Additional metadata for filtering
      media_type: post.type || (post.image_link ? 'image' : 'text'),
      has_location: !!(post.location),
      word_count: post.description ? post.description.split(' ').length : 0,
      size: post.file_size || post.size || 0, // Extract file size from API
      capture_time: post.capture_time || null,
      capture_date: post.capture_date || post.created_at || new Date().toISOString(),
      dimensions: post.dimensions || post.image_dimensions || null, // Extract dimensions
      width: post.width || post.image_width || null,
      height: post.height || post.image_height || null,
      city: post.city || null,
      country: post.country || null,
      coordinates: post.coordinates || post.lat_lng || null,
      description: post.description || '', // Explicit description field
      rotation_angle: post.rotation_angle || 0, // Add rotation angle from API
      admin_approval: post.admin_approval, // Preserve admin_approval field for moderation
      parent_id: post.parent_id || null, // Preserve parent_id field for sub-images
      is_featured: post.is_featured || 0, // Preserve is_featured field (0 or 1) for featured images
      hide_caption: post.hide_caption || 0, // Preserve hide_caption field (0 or 1)
      crop_data: post.crop_data || null, // Preserve crop_data if available
      is_claim: post.is_claim || null, // Preserve is_claim field for claim status
      claim_user_id: post.claim_user_id || null, // Preserve claim_user_id field
      is_new: post.is_new ?? null, // Preserve is_new field for new badge
      after_post_id: post.after_post_id ?? null // Preserve after_post_id for chain ordering
      };
    });
  };

  // Get posts from API data
  const rawApiPosts = apiMemoryData?.posts;
  
  console.log('=== POST DATA EXTRACTION ===');
  console.log('API Memory Data Keys:', Object.keys(apiMemoryData || {}));
  console.log('Raw API Posts Found:', rawApiPosts);
  console.log('Posts Array Length:', Array.isArray(rawApiPosts) ? rawApiPosts.length : 'Not an array');
  console.log('First Post Sample:', rawApiPosts?.[0]);
  console.log('Posts with parent_id:', rawApiPosts?.filter((p: any) => p.parent_id).map((p: any) => ({ id: p.id, parent_id: p.parent_id })));
  console.log('=== END POST DATA EXTRACTION ===');

  const apiPosts = rawApiPosts ? transformApiPosts(rawApiPosts) : [];

  console.log('=== TRANSFORMED POSTS ===');
  console.log('Transformed posts with parent_id:', apiPosts.filter(p => p.parent_id).map(p => ({ id: p.id, parent_id: p.parent_id })));
  console.log('=== END TRANSFORMED POSTS ===');

  console.log('=== ADMIN APPROVAL FILTERING ===');
  apiPosts.forEach(post => {
    console.log(`Post ID: ${post.id}, admin_approval: ${post.admin_approval}`);
  });

  // Filter pending posts for moderation (admin_approval = 0) - these should only appear in moderation tab
  const pendingPosts = rawApiPosts ? rawApiPosts.filter((post: any) => post.admin_approval === 0 || post.admin_approval === '0') : [];
  const pendingPostsCount = pendingPosts.length;
  // Combined moderation count = pending moments + pending widgets (both awaiting approval)
  const pendingModerationCount = pendingPostsCount + pendingWidgets.length;

  // Dynamic tab configuration - all tabs defined here with their conditions
  const tabItems = [
    { key: 'overview', label: 'Timeline', enabled: true, icon: 'clock', badge: 0 },
    { key: 'analytics', label: 'Analytics', enabled: true, icon: 'chart', badge: 0 },
    { key: 'moderation', label: 'Moderation', enabled: shouldShowModeration, icon: 'shield', badge: shouldShowModeration ? pendingModerationCount : 0 },
    { key: 'collaborators', label: 'Users', enabled: true, icon: 'users', badge: 0 },
  ];

  // Filter out posts with admin_approval = 0 from regular display (media section)
  // Now showing sub-images in media section (not hiding them anymore)
  // Only show approved posts (admin_approval = 1 or undefined/null for backward compatibility)
  const approvedApiPosts = apiPosts.filter(post => {
    const adminApproval = post.admin_approval;
    const parentId = post.parent_id;

    // Show posts that are approved (1) or don't have the field (undefined/null for backward compatibility)
    // Exclude posts with admin_approval = 0 (pending approval)
    if (adminApproval === 0 || adminApproval === '0') {
      console.log(`🚫 Filtering out post ${post.id} - admin_approval = ${adminApproval}`);
      return false; // Hide pending posts from media section
    }

    console.log(`✅ Keeping post ${post.id} - admin_approval = ${adminApproval}, parent_id = ${parentId}`);
    return adminApproval === 1 || adminApproval === '1' || adminApproval === undefined || adminApproval === null;
  });
  console.log('=== END ADMIN APPROVAL FILTERING ===');

  const basePosts = approvedApiPosts;

  // Apply local content and comment count updates
  const memoryPosts = basePosts.map(post => ({
    ...post,
    content: updatedPosts[post.id] || post.content,
    comments: updatedCommentCounts[post.id] !== undefined ? updatedCommentCounts[post.id] : post.comments
  }));

  // Organize images with their sub-images for AddMomentModal
  const memoryImagesWithSubImages = memoryPosts
    .filter(post => !post.parent_id) // Only parent images
    .map(parentPost => {
      // Find all sub-images for this parent
      const subImages = memoryPosts
        .filter(post => post.parent_id?.toString() === parentPost.id?.toString())
        .map(subPost => ({
          id: subPost.id,
          src: subPost.image || '',
          title: subPost.title || subPost.name || 'Untitled',
          tags: Array.isArray(subPost.tags) ? subPost.tags : []
        }));

      return {
        id: parentPost.id,
        src: parentPost.image || '',
        title: parentPost.title || parentPost.name || 'Untitled',
        subImages: subImages
      };
    });

  console.log('=== MEMORY POSTS ANALYSIS ===');
  console.log('Raw API Posts:', rawApiPosts);
  console.log('Transformed API Posts:', apiPosts);
  console.log('Pending Posts for Moderation (admin_approval=0):', pendingPosts);
  console.log('Pending Posts Count:', pendingPostsCount);
  console.log('Approved Posts (admin_approval=1 or null):', approvedApiPosts);
  console.log('Approved Posts Count:', approvedApiPosts.length);
  console.log('Memory Images with Sub-images:', memoryImagesWithSubImages);
  console.log('Memory posts data:', {
    hasApiPosts: !!rawApiPosts,
    apiPostsCount: apiPosts.length,
    totalPostsCount: memoryPosts.length,
    posts: memoryPosts,
    samplePost: memoryPosts[0],
    postsWithFiltering: memoryPosts.map(post => ({
      id: post.id,
      hasMedia: !!(post.image || post.media_type === 'image'),
      hasLocation: !!(post.location || post.has_location),
      type: post.type || 'unknown',
      media_type: post.media_type,
      likes: post.likes,
      likes_count: post.likes_count,
      comments: post.comments,
      is_liked: post.is_liked,
      shares_count: post.shares_count,
      timestamp: post.timestamp
    }))
  });
  console.log('=== END MEMORY POSTS ANALYSIS ===');

  // Check if current user is the memory owner

  // Enhanced filtering and sorting for posts based on timeline filter
  const getFilteredAndSortedPosts = () => {
    // First, apply any updates from updatedPosts state and filter out deleted posts and sub-images
    let filteredPosts = memoryPosts
      .filter(post => !deletedPosts.has(post.id)) // Filter out deleted posts
      .filter(post => !post.parent_id) // Filter out sub-images - only show parent posts on timeline
      .map(post => {
        // Check if this post has an update in updatedPosts
        if (updatedPosts[post.id] !== undefined) {
          return {
            ...post,
            content: updatedPosts[post.id]
          };
        }
        return post;
      });

    // If custom drag-and-drop order exists, use that instead of filter-based sorting
    if (customPostOrder.length > 0) {
      const orderMap = new Map(customPostOrder.map((id, i) => [id, i]));
      const ordered = filteredPosts.filter(p => orderMap.has(p.id));
      const remaining = filteredPosts.filter(p => !orderMap.has(p.id));
      ordered.sort((a, b) => (orderMap.get(a.id) ?? 0) - (orderMap.get(b.id) ?? 0));
      return [...ordered, ...remaining];
    }

    // If any post has after_post_id set, build order using the after_post_id chain
    const hasAfterPostId = filteredPosts.some(p => p.after_post_id != null);
    if (hasAfterPostId) {
      // Group posts by what they come after
      const afterMap: Record<string, any[]> = {};
      const rootPosts: any[] = [];

      filteredPosts.forEach(post => {
        if (post.after_post_id == null) {
          rootPosts.push(post);
        } else {
          const key = String(post.after_post_id);
          if (!afterMap[key]) afterMap[key] = [];
          afterMap[key].push(post);
        }
      });

      // Sort root posts by capture_date descending
      rootPosts.sort((a, b) => {
        const aTime = new Date(a.capture_date || a.date || a.timestamp).getTime();
        const bTime = new Date(b.capture_date || b.date || b.timestamp).getTime();
        return bTime - aTime;
      });

      // Recursively insert children after their parent
      const result: any[] = [];
      const insertPost = (post: any) => {
        result.push(post);
        const children = afterMap[String(post.id)];
        if (children) {
          children.sort((a: any, b: any) => (a.id ?? 0) - (b.id ?? 0));
          children.forEach(insertPost);
        }
      };

      rootPosts.forEach(insertPost);

      // Append any posts not yet added (safety fallback)
      filteredPosts.forEach(p => {
        if (!result.find((r: any) => r.id === p.id)) result.push(p);
      });

      return result;
    }

    // Sort posts based on timeline filter
    return filteredPosts.sort((a, b) => {
      // Check if either post has a featured sub-image
      const aHasFeaturedSubImage = memoryPosts.some(p =>
        p.parent_id?.toString() === a.id?.toString() && (p.is_featured === 1 || p.is_featured === true)
      );
      const bHasFeaturedSubImage = memoryPosts.some(p =>
        p.parent_id?.toString() === b.id?.toString() && (p.is_featured === 1 || p.is_featured === true)
      );

      // Posts with featured sub-images come first
      if (aHasFeaturedSubImage && !bHasFeaturedSubImage) return -1;
      if (!aHasFeaturedSubImage && bHasFeaturedSubImage) return 1;

      // Apply normal sorting
      switch (timelineFilter) {
        case "latest":
          // Sort by capture_date (newest first)
          const aTime = new Date(a.capture_date || a.date || a.timestamp).getTime();
          const bTime = new Date(b.capture_date || b.date || b.timestamp).getTime();
          return bTime - aTime;
        case "oldest":
          // Sort by capture_date (oldest first)
          const aTimeOld = new Date(a.capture_date || a.date || a.timestamp).getTime();
          const bTimeOld = new Date(b.capture_date || b.date || b.timestamp).getTime();
          return aTimeOld - bTimeOld;
        case "fewer_comments":
          // Sort by fewer comments first
          return (a.comments || 0) - (b.comments || 0);
        case "most_comments":
          // Sort by most comments first
          return (b.comments || 0) - (a.comments || 0);
        default:
          return 0;
      }
    });
  };

  const sortedTimelinePosts = getFilteredAndSortedPosts();
  sortedTimelinePostsRef.current = sortedTimelinePosts;
  // "N moments" in the Timeline header should count linked memories (incl. car listings) too,
  // not just this memory's own posts — otherwise a memory made entirely of linked items shows 0.
  const totalMomentsCount = sortedTimelinePosts.length + (apiMemoryData?.linked_memories?.length || 0);

  // Client-side search: find which posts contain the active search query (plain value, no hook)
  const searchMatchIndices: number[] = activeSearchQuery.trim()
    ? sortedTimelinePosts.reduce((acc: number[], post, idx) => {
        const q = activeSearchQuery.toLowerCase();
        const text = (post.description || post.title || post.content || '').toLowerCase();
        const postTags = Array.isArray(post.tags)
          ? post.tags.map((t: any) => (typeof t === 'string' ? t : t?.name || '')).join(' ').toLowerCase()
          : '';
        if (text.includes(q) || postTags.includes(q)) acc.push(idx);
        return acc;
      }, [])
    : [];

  // Helper to highlight matched text with yellow background
  const highlightText = (text: string, query: string): React.ReactNode => {
    if (!query || !text) return text;
    const escaped = query.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const parts = text.split(new RegExp(`(${escaped})`, 'gi'));
    return (
      <>
        {parts.map((part, i) =>
          part.toLowerCase() === query.toLowerCase()
            ? <mark key={i} style={{ background: '#FDE047', color: 'inherit', borderRadius: '2px', padding: '0 1px' }}>{part}</mark>
            : part
        )}
      </>
    );
  };

  // Submit search (Enter or search icon click)
  const handleSearchSubmit = () => {
    const q = searchQuery.trim();
    if (!q) return;
    setActiveSearchQuery(q);
    setCurrentSearchMatchIndex(0);
    // Scroll to first match
    setTimeout(() => {
      const idx = sortedTimelinePosts.findIndex((post) => {
        const text = (post.description || post.title || post.content || '').toLowerCase();
        return text.includes(q.toLowerCase());
      });
      if (idx !== -1) {
        memoryCardRefs.current[idx]?.scrollIntoView({ behavior: 'smooth', block: 'center' });
        timelineItemRefs.current[idx]?.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
      }
    }, 50);
  };

  // Navigate to next/prev match
  const handleSearchNav = (direction: 'next' | 'prev') => {
    if (searchMatchIndices.length === 0) return;
    const total = searchMatchIndices.length;
    const newMatchIdx = direction === 'next'
      ? (currentSearchMatchIndex + 1) % total
      : (currentSearchMatchIndex - 1 + total) % total;
    setCurrentSearchMatchIndex(newMatchIdx);
    const postIdx = searchMatchIndices[newMatchIdx];
    memoryCardRefs.current[postIdx]?.scrollIntoView({ behavior: 'smooth', block: 'center' });
    timelineItemRefs.current[postIdx]?.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
  };

  // Clear search
  const handleSearchClear = () => {
    setSearchQuery("");
    setActiveSearchQuery("");
    setCurrentSearchMatchIndex(0);
  };

  // Helper function to extract filename from URL or generate one
  const getFileNameFromPost = (post: any) => {
    // First priority: Check if posts array has a name field
    if (post.name && post.name.trim()) {
      return post.name;
    }
    
    // Second priority: Extract from image_link if available
    if (post.image) {
      // Try to extract filename from URL
      const urlParts = post.image.split('/');
      const filename = urlParts[urlParts.length - 1];
      
      // If filename has proper extension, use it
      if (filename && (filename.includes('.jpg') || filename.includes('.jpeg') || filename.includes('.png') || filename.includes('.gif'))) {
        return filename;
      }
      
      // Otherwise generate filename from author and date
      const dateStr = (post.capture_date || post.date || new Date().toISOString()).split('T')[0];
      return `${post.author.name.replace(/\s+/g, '_')}_${dateStr}.jpg`;
    }
    
    // For text posts
    return `Text_Post_${post.id}.txt`;
  };

  // Helper function to format file size
  const formatFileSize = (bytes: number | string): string => {
    const size = typeof bytes === 'string' ? parseInt(bytes) || 0 : bytes;
    if (size === 0) return '2.4 MB'; // Default size if not provided
    
    const k = 1024;
    const sizes = ['B', 'KB', 'MB', 'GB'];
    const i = Math.floor(Math.log(size) / Math.log(k));
    return parseFloat((size / Math.pow(k, i)).toFixed(1)) + ' ' + sizes[i];
  };

  // Helper function to extract or estimate image dimensions
  const getImageDimensions = (post: any): string => {
    // Check if dimensions are provided in the API
    if (post.dimensions) return post.dimensions;
    if (post.width && post.height) return `${post.width}×${post.height}`;
    
    // Default dimensions based on type
    if (post.media_type === 'video') return '1920×1080';
    if (post.image) return '4032×3024'; // Common phone camera dimensions
    
    return undefined;
  };

  // Transform posts to media items for the media section
  const transformPostsToMediaItems = (posts: any[]) => {
    return posts.map((post) => {
      // Get the type from the post - this could be 'fb', 'facebook', 'instagram', 'image', 'video', 'text'
      const rawType = post.type || 'image';
      let mediaType: 'image' | 'video' | 'text' = 'image';
      let sourcePlatform: string | null = null;

      // Check if type indicates a platform (fb, facebook, instagram, etc.)
      if (rawType.toLowerCase() === 'fb' || rawType.toLowerCase() === 'facebook') {
        mediaType = 'image'; // It's an image from Facebook
        sourcePlatform = 'facebook'; // Use 'facebook' as the source
      } else if (rawType.toLowerCase() === 'instagram') {
        mediaType = 'image';
        sourcePlatform = 'instagram';
      } else if (['image', 'video', 'text'].includes(rawType.toLowerCase())) {
        mediaType = rawType.toLowerCase() as 'image' | 'video' | 'text';
        sourcePlatform = null; // No platform source
      } else {
        // Unknown type, treat as platform source
        mediaType = 'image';
        sourcePlatform = rawType;
      }

      const imageUrl = post.image_link || post.image || null;

      // Get the file name, and if this is a sub-image, prepend parent image name for display
      let itemName = getFileNameFromPost(post);
      const originalName = itemName; // Store original name without parent prefix

      // Check if this post has a parent_id (meaning it's a sub-image)
      if (post.parent_id) {
        // Find the parent post
        const parentPost = posts.find(p => p.id?.toString() === post.parent_id?.toString());
        if (parentPost) {
          const parentName = getFileNameFromPost(parentPost);
          // Truncate parent name to max 10 chars to ensure "/" is visible on card
          const truncatedParentName = parentName.length > 10 ? parentName.substring(0, 10) + '...' : parentName;
          itemName = `${truncatedParentName} / ${itemName}`; // Display name with parent prefix
          console.log(`📎 Sub-image detected: ${post.id}, parent: ${post.parent_id}, name: ${itemName}`);
        }
      }

      const mediaItem = {
        id: post.id,
        name: itemName, // Display name (with parent prefix for sub-images)
        originalName: originalName, // Original name without prefix
        title: post.title || '', // Post title from API
        thumbnail: imageUrl,
        image: imageUrl,
        type: mediaType,
        size: formatFileSize(post.size || (imageUrl ? 2515456 : 1024)),
        date: post.capture_date || post.timestamp || post.date || new Date().toISOString(),
        location: post.location ? {
          displayName: post.location,
          city: post.city,
          country: post.country,
          coordinates: post.coordinates || { lat: 0, lng: 0 }
        } : undefined,
        author: {
          name: (post.user || post.author)?.name || 'Unknown',
          avatar: (post.user || post.author)?.avatar || (post.user || post.author)?.profile_image || '',
          id: (post.user || post.author)?.id?.toString() || (post.user || post.author)?.user_id?.toString()
        },
        content: post.content,
        description: post.description || post.content || '',
        dimensions: getImageDimensions(post),
        labels: Array.isArray(post.tags) ? post.tags.map((t: any) => typeof t === 'string' ? t : t?.name).filter(Boolean) : [],
        rotation_angle: post.rotation_angle || 0,
        source: sourcePlatform,
        parent_id: post.parent_id, // Include parent_id so we can detect sub-images
        is_featured: post.is_featured || 0, // Include is_featured for sorting
        hide_caption: post.hide_caption || 0, // Include hide_caption so the timeline can hide it
        is_new: post.is_new // Include is_new for new badge
      };

      console.log(`🖼️ Media Item ${post.id}: type="${post.type}" -> source="${sourcePlatform}" | is_new=${post.is_new} (${typeof post.is_new})`);

      return mediaItem;
    });
  };

  const mediaItems = transformPostsToMediaItems(memoryPosts);

  // Sort media items
  const sortMediaItems = (items: any[], sortBy: string, order: 'asc' | 'desc') => {
    return [...items].sort((a, b) => {
      // Featured images always come first
      const aIsFeatured = a.is_featured === 1 || a.is_featured === true;
      const bIsFeatured = b.is_featured === 1 || b.is_featured === true;

      if (aIsFeatured && !bIsFeatured) return -1;
      if (!aIsFeatured && bIsFeatured) return 1;

      // If both or neither are featured, apply normal sorting
      let comparison = 0;

      switch (sortBy) {
        case 'date':
          comparison = new Date(a.date).getTime() - new Date(b.date).getTime();
          break;
        case 'name':
          comparison = a.name.localeCompare(b.name);
          break;
        case 'size':
          const aSize = typeof a.size === 'string' ? parseInt(a.size) : a.size;
          const bSize = typeof b.size === 'string' ? parseInt(b.size) : b.size;
          comparison = aSize - bSize;
          break;
        default:
          return 0;
      }

      return order === 'asc' ? comparison : -comparison;
    });
  };

  const filteredAndSortedMediaItems = sortMediaItems(mediaItems, mediaSortBy, mediaSortOrder);

  // Reordered media items for grid display (drag-and-drop)
  const displayMediaItems = (() => {
    if (mediaCustomOrder.length === 0) return filteredAndSortedMediaItems;
    const orderMap = new Map(mediaCustomOrder.map((id, i) => [id, i]));
    const ordered: typeof filteredAndSortedMediaItems = [];
    const remaining: typeof filteredAndSortedMediaItems = [];
    for (const item of filteredAndSortedMediaItems) {
      if (orderMap.has(item.id)) {
        ordered.push(item);
      } else {
        remaining.push(item);
      }
    }
    ordered.sort((a, b) => (orderMap.get(a.id) ?? 0) - (orderMap.get(b.id) ?? 0));
    return [...ordered, ...remaining];
  })();

