  // Helper to format total_size (MB) into a readable value + unit
  const formatStorageSize = (sizeInMB: number): { value: string; unit: string } => {
    if (!sizeInMB || sizeInMB <= 0) return { value: '0', unit: 'MB' };
    if (sizeInMB < 1) return { value: (sizeInMB * 1024).toFixed(1), unit: 'KB' };
    if (sizeInMB < 1024) return { value: sizeInMB.toFixed(1), unit: 'MB' };
    return { value: (sizeInMB / 1024).toFixed(2), unit: 'GB' };
  };

  // Helper function to check if URL is a video
  const isVideoUrl = (url: string): boolean => {
    if (!url) return false;
    const videoExtensions = ['.mp4', '.mov', '.avi', '.webm', '.mkv', '.m4v'];
    const lowerUrl = url.toLowerCase();
    return videoExtensions.some(ext => lowerUrl.includes(ext));
  };

  // Helper to detect YouTube URLs
  const isYoutubeUrl = (url: string): boolean => {
    if (!url) return false;
    return /youtube\.com\/watch|youtu\.be\/|youtube\.com\/shorts\/|youtube\.com\/embed\//.test(url);
  };

  // Convert any YouTube URL format to embed URL (no autoplay — user controls play/pause)
  const getYoutubeEmbedUrl = (url: string): string | null => {
    if (!url) return null;
    const params = 'autoplay=0';
    let match = url.match(/youtu\.be\/([a-zA-Z0-9_-]+)/);
    if (match) return `https://www.youtube.com/embed/${match[1]}?${params}`;
    match = url.match(/youtube\.com\/shorts\/([a-zA-Z0-9_-]+)/);
    if (match) return `https://www.youtube.com/embed/${match[1]}?${params}`;
    match = url.match(/[?&]v=([a-zA-Z0-9_-]+)/);
    if (match) return `https://www.youtube.com/embed/${match[1]}?${params}`;
    if (url.includes('youtube.com/embed/')) return url;
    return null;
  };

