  // Helper function to get video duration
  const getVideoDuration = (file: File): Promise<number> => {
    return new Promise((resolve, reject) => {
      const video = document.createElement('video');
      video.preload = 'metadata';

      video.onloadedmetadata = () => {
        window.URL.revokeObjectURL(video.src);
        const duration = video.duration;
        if (isNaN(duration) || !isFinite(duration)) {
          reject(new Error('Invalid video duration'));
        } else {
          resolve(duration);
        }
      };

      video.onerror = () => {
        window.URL.revokeObjectURL(video.src);
        reject(new Error('Failed to load video'));
      };

      video.src = URL.createObjectURL(file);
    });
  };

  const handleUploadFromDesktop = () => {
    console.log('🖼️ Upload from Desktop clicked');
    setIsCoverPhotoMenuOpen(false);

    // Create a hidden file input element
    const fileInput = document.createElement('input');
    fileInput.type = 'file';
    // Use explicit extensions on mobile to bypass iOS/Android native action sheet
    fileInput.accept = isMobile ? MOBILE_ALL_EXTENSIONS : 'image/*,video/*';
    fileInput.style.display = 'none';

    fileInput.onchange = async (e: Event) => {
      console.log('📁 File input changed');
      const target = e.target as HTMLInputElement;
      const file = target.files?.[0];

      if (!file) {
        console.log('❌ No file selected');
        return;
      }

      console.log('✅ File selected:', file.name, file.size, file.type);

      const isImage = file.type.startsWith('image/');
      const isVideo = file.type.startsWith('video/');

      // Validate file type
      if (!isImage && !isVideo) {
        toast.error('Please select an image or video file');
        return;
      }

      // Validate file size based on type
      if (isImage) {
        const maxImageSize = 10 * 1024 * 1024; // 10MB for images
        if (file.size > maxImageSize) {
          toast.error('Image size must be less than 10MB');
          return;
        }
      } else if (isVideo) {
        

        // Validate video duration (must be <= 2 minutes)
        try {
          const duration = await getVideoDuration(file);
          console.log('🎬 Video duration:', duration, 'seconds');

          if (duration > 120) {
            const minutes = Math.floor(duration / 60);
            const seconds = Math.floor(duration % 60);
            toast.error(`Video is too long (${minutes}m ${seconds}s). Maximum duration is 2 minutes.`);
            return;
          }
        } catch (error) {
          console.error('❌ Error checking video duration:', error);
          toast.error('Unable to validate video duration. Please try again.');
          return;
        }
      }

      try {
        console.log('🚀 Starting cover photo upload...');
        console.log('Memory ID:', memoryId);
        setCoverUploadType(isVideo ? 'video' : 'photo');
        setIsCoverUploading(true);
        setCoverUploadProgress(0);
        toast.loading(isVideo ? 'Uploading cover video...' : 'Uploading cover photo...');

        // Create FormData for multipart upload
        const formData = new FormData();
        formData.append('_method', 'PUT');
        formData.append('last_update_img', file);

        // Get auth token
        const token = tokenUtils.getToken();

        // Get API base URL
        const getApiBaseUrl = () => {
          if (import.meta.env.VITE_API_BASE_URL) return import.meta.env.VITE_API_BASE_URL;
          if (import.meta.env.DEV) return '/api/react';
          return `${window.location.origin}/api/react`;
        };

        const apiUrl = `${getApiBaseUrl()}/memories/${memoryId}`;
        console.log('🌐 API URL:', apiUrl);

        // Use XMLHttpRequest with time-based progress simulation
        // Phase 1: 0%→50% in ~30s (600ms/step)
        // Phase 2: 50%→70% in ~25s (1250ms/step)
        // Phase 3: 70%→99% in ~35s (1200ms/step)
        // 100% only on actual server response
        const data = await new Promise<any>((resolve, reject) => {
          const xhr = new XMLHttpRequest();
          let currentInterval: ReturnType<typeof setInterval> | null = null;
          let currentProgress = 0;

          const clearInterval_ = () => {
            if (currentInterval) { clearInterval(currentInterval); currentInterval = null; }
          };

          // Start phase-based progress simulation
          const startProgressSimulation = () => {
            // Phase 1: 0 → 50 in 30s (600ms per 1%)
            currentInterval = setInterval(() => {
              currentProgress += 1;
              setCoverUploadProgress(currentProgress);

              if (currentProgress >= 50) {
                clearInterval_();

                // Phase 2: 50 → 70 in 25s (1250ms per 1%)
                currentInterval = setInterval(() => {
                  currentProgress += 1;
                  setCoverUploadProgress(currentProgress);

                  if (currentProgress >= 70) {
                    clearInterval_();

                    // Phase 3: 70 → 99 in 35s (1200ms per 1%)
                    currentInterval = setInterval(() => {
                      currentProgress += 1;
                      setCoverUploadProgress(currentProgress);
                      if (currentProgress >= 99) {
                        clearInterval_();
                      }
                    }, 1200);
                  }
                }, 1250);
              }
            }, 600);
          };

          xhr.upload.onloadstart = () => {
            startProgressSimulation();
          };

          xhr.onload = () => {
            clearInterval_();
            setCoverUploadProgress(100);
            try {
              resolve({ status: xhr.status, body: JSON.parse(xhr.responseText) });
            } catch {
              reject(new Error('Invalid JSON response'));
            }
          };

          xhr.onerror = () => { clearInterval_(); reject(new Error('Network error')); };

          xhr.open('POST', apiUrl);
          if (token) xhr.setRequestHeader('Authorization', `Bearer ${token}`);
          xhr.send(formData);
        });

        console.log('📨 Response status:', data.status);
        console.log('📨 Response data:', data.body);

        if (data.status >= 200 && data.status < 300 && data.body?.success) {
          toast.dismiss();
          toast.success(isVideo ? 'Cover video updated successfully!' : 'Cover photo updated successfully!');
          console.log('🔄 Refreshing memory details...');
          await fetchMemoryDetails(true);
          if (onRefresh) await onRefresh();
        } else {
          toast.dismiss();
          toast.error(data.body?.message || data.body?.error || (isVideo ? 'Failed to update cover video' : 'Failed to update cover photo'));
        }
      } catch (error) {
        console.error('❌ Error uploading cover:', error);
        toast.dismiss();
        toast.error(isVideo ? 'Failed to upload cover video. Please try again.' : 'Failed to upload cover photo. Please try again.');
      } finally {
        setIsCoverUploading(false);
        setCoverUploadProgress(0);
      }
    };

    // Append to body temporarily to ensure it works
    document.body.appendChild(fileInput);

    // Trigger file selection
    console.log('🖱️ Triggering file input click...');
    fileInput.click();

    // Remove from body after a short delay
    setTimeout(() => {
      document.body.removeChild(fileInput);
    }, 1000);
  };

  // Mobile-friendly file extensions that bypass iOS "Photo Library / Take Photo / Choose File" action sheet
  const MOBILE_IMAGE_EXTENSIONS = '.jpg,.jpeg,.png,.heic,.heif,.gif,.webp';
  const MOBILE_ALL_EXTENSIONS = '.jpg,.jpeg,.png,.heic,.heif,.gif,.webp,.mp4,.mov,.m4v,.3gp';

  // Trigger mobile-friendly file picker that bypasses iOS action sheet
  // Uses explicit file extensions instead of MIME wildcards to skip the native popup
  const triggerMobileFilePicker = (onChange: (e: Event) => void, includeVideo = true) => {
    const input = document.createElement('input');
    input.type = 'file';
    input.accept = includeVideo ? MOBILE_ALL_EXTENSIONS : MOBILE_IMAGE_EXTENSIONS;
    input.style.display = 'none';
    input.onchange = (e: Event) => {
      onChange(e);
      // Cleanup
      setTimeout(() => { if (input.parentNode) input.parentNode.removeChild(input); }, 500);
    };
    document.body.appendChild(input);
    input.click();
  };

