  // Drag-and-drop reorder handlers
  const handleMediaDragStart = (e: React.DragEvent<HTMLDivElement>, itemId: string) => {
    setDraggedMediaId(itemId);
    e.dataTransfer.effectAllowed = 'move';
    (e.currentTarget as HTMLDivElement).style.opacity = '0.4';
    // Custom white drag icon
    const dragIcon = document.createElement('div');
    dragIcon.style.cssText = 'width:48px;height:48px;display:flex;align-items:center;justify-content:center;position:absolute;top:-9999px;left:-9999px;';
    dragIcon.innerHTML = '<svg width="24" height="24" viewBox="0 0 512 512" fill="white" xmlns="http://www.w3.org/2000/svg"><path d="M278.6 9.4c-12.5-12.5-32.8-12.5-45.3 0l-64 64c-12.5 12.5-12.5 32.8 0 45.3s32.8 12.5 45.3 0l9.4-9.4V224H99.3l9.4-9.4c12.5-12.5 12.5-32.8 0-45.3s-32.8-12.5-45.3 0l-64 64c-12.5 12.5-12.5 32.8 0 45.3l64 64c12.5 12.5 32.8 12.5 45.3 0s12.5-32.8 0-45.3L99.3 288H224v124.7l-9.4-9.4c-12.5-12.5-32.8-12.5-45.3 0s-12.5 32.8 0 45.3l64 64c12.5 12.5 32.8 12.5 45.3 0l64-64c12.5-12.5 12.5-32.8 0-45.3s-32.8-12.5-45.3 0l-9.4 9.4V288h124.7l-9.4 9.4c-12.5 12.5-12.5 32.8 0 45.3s32.8 12.5 45.3 0l64-64c12.5-12.5 12.5-32.8 0-45.3l-64-64c-12.5-12.5-32.8-12.5-45.3 0s-12.5 32.8 0 45.3l9.4 9.4H288V109.3l9.4 9.4c12.5 12.5 32.8 12.5 45.3 0s12.5-32.8 0-45.3l-64-64z"/></svg>';
    document.body.appendChild(dragIcon);
    e.dataTransfer.setDragImage(dragIcon, 24, 24);
    setTimeout(() => document.body.removeChild(dragIcon), 0);
  };

  const handleMediaDragOver = (e: React.DragEvent<HTMLDivElement>, itemId: string) => {
    e.preventDefault();
    e.dataTransfer.dropEffect = 'move';
    if (itemId !== draggedMediaId) {
      setDragOverMediaId(itemId);
    }
  };

  const handleMediaDragLeave = () => {
    setDragOverMediaId(null);
  };

  const handleMediaDrop = (e: React.DragEvent<HTMLDivElement>, targetId: string) => {
    e.preventDefault();
    setDragOverMediaId(null);
    if (!draggedMediaId || draggedMediaId === targetId) return;

    const currentOrder = mediaCustomOrder.length > 0
      ? [...mediaCustomOrder]
      : displayMediaItems.map(item => item.id);

    const sourceIdx = currentOrder.indexOf(draggedMediaId);
    const targetIdx = currentOrder.indexOf(targetId);
    if (sourceIdx === -1 || targetIdx === -1) return;

    currentOrder.splice(sourceIdx, 1);
    currentOrder.splice(targetIdx, 0, draggedMediaId);
    setMediaCustomOrder(currentOrder);

    // Sync timeline/cards order: filter out sub-images (only parent posts appear on timeline)
    const parentOnlyOrder = currentOrder.filter(id => {
      const post = memoryPosts.find(p => p.id === id);
      return post && !post.parent_id;
    });
    setCustomPostOrder(parentOnlyOrder);
  };

  const handleMediaDragEnd = (e: React.DragEvent<HTMLDivElement>) => {
    (e.currentTarget as HTMLDivElement).style.opacity = '1';
    setDraggedMediaId(null);
    setDragOverMediaId(null);
  };

